from __future__ import annotations

import json
from datetime import datetime, timezone

from gitseed.application import execute
from gitseed.cli import main
from gitseed.collect.search import Candidate, CollectResult
from gitseed.grade.smoke import SmokeResult
from gitseed.grade.types import GradeResult
from gitseed.pipeline.run import FetchedFiles
from gitseed.ports import RepositoryMetadata, RunPorts, RunRequest
from gitseed.scoring import ScoreInputs


class _Repository:
    def __init__(self, candidate: Candidate) -> None:
        self._candidate = candidate

    def search(self, query: str, limit: int) -> CollectResult:
        return CollectResult(candidates=(self._candidate,))

    def metadata(self, candidate: Candidate, at: datetime) -> RepositoryMetadata:
        return RepositoryMetadata(ScoreInputs(True, True, True))


class _Files:
    def __init__(self, unavailable: bool) -> None:
        self._unavailable = unavailable

    def read(self, candidate: Candidate) -> FetchedFiles:
        if self._unavailable:
            raise OSError("source read failed")
        return FetchedFiles((("main.py", "def add(a, b):\n    return a + b\n"),))


class _Grader:
    def evaluate(self, digest: str) -> GradeResult:
        return GradeResult(7, 7, "small utility", "test", 0.0, "test-v1")

    def flags_malicious(self, digest: str) -> bool:
        return False


class _Clock:
    def now(self) -> datetime:
        return datetime(2026, 1, 1, tzinfo=timezone.utc)


def _write_artifact(path, repo: str, *, unavailable: bool) -> None:
    candidate = Candidate(repo, "example", "", 1, "")
    artifact = execute(
        RunRequest("example", 1, ("coding-agents",)),
        RunPorts(_Repository(candidate), _Files(unavailable), _Grader(), _Clock()),
        model_smoke=SmokeResult(True, "test"),
    )
    path.write_bytes(artifact.to_bytes())


def test_cli_distinguishes_unavailable_category_evidence_from_a_verified_non_match(tmp_path, capsys) -> None:
    unavailable_artifact = tmp_path / "unavailable.json"
    unmatched_artifact = tmp_path / "unmatched.json"
    _write_artifact(unavailable_artifact, "example/unavailable", unavailable=True)
    _write_artifact(unmatched_artifact, "example/unmatched", unavailable=False)

    unavailable_label = "coding-agents: unavailable evidence: files, source"
    unmatched_label = "coding-agents: uncategorized (deterministic)"

    assert main(["radar", "--render", str(unavailable_artifact)]) == 2
    unavailable_table = capsys.readouterr().out
    assert unavailable_label in next(
        line for line in unavailable_table.splitlines() if "example/unavailable" in line
    )

    assert main(["radar", "--render", str(unavailable_artifact), "--json"]) == 2
    unavailable_json = json.loads(capsys.readouterr().out)
    assert unavailable_json[0]["category"] == unavailable_label

    assert main(["explain", "example/unavailable", "--artifact", str(unavailable_artifact)]) == 2
    assert f"category: {unavailable_label}\n" in capsys.readouterr().out

    assert main(["radar", "--render", str(unmatched_artifact)]) == 0
    unmatched_table = capsys.readouterr().out
    assert unmatched_label in next(
        line for line in unmatched_table.splitlines() if "example/unmatched" in line
    )

    assert main(["radar", "--render", str(unmatched_artifact), "--json"]) == 0
    unmatched_json = json.loads(capsys.readouterr().out)
    assert unmatched_json[0]["category"] == unmatched_label

    assert main(["explain", "example/unmatched", "--artifact", str(unmatched_artifact)]) == 0
    assert f"category: {unmatched_label}\n" in capsys.readouterr().out
